mapper.select:
WITH candidate AS (
    SELECT ctid
    FROM ut_asset_outbox
    WHERE (
        status IN (#{pendingStatus}, #{failedStatus})
        AND (next_retry_at IS NULL OR next_retry_at <= NOW())
    ) OR (
        status = #{publishingStatus}
        AND updated_at <= #{staleBefore}
    )
    ORDER BY created_at, id
    LIMIT #{batchSize}
    FOR UPDATE SKIP LOCKED
)
UPDATE ut_asset_outbox outbox
SET status = #{publishingStatus}, updated_at = NOW()
FROM candidate
WHERE outbox.ctid = candidate.ctid
RETURNING outbox.*

mapper.update:
UPDATE ut_asset_outbox
SET status = #{publishedStatus}, published_at = #{publishedAt},
    next_retry_at = NULL, updated_at = #{publishedAt}
WHERE id = #{id} AND status = #{publishingStatus}

UPDATE ut_asset_outbox
SET status = #{outbox.status}, retry_count = #{outbox.retryCount},
    next_retry_at = #{outbox.nextRetryAt}, updated_at = #{outbox.updatedAt}
WHERE id = #{outbox.id} AND status = #{publishingStatus}
